import logger from "../Logger";
import { parseSocketUrl } from "./ParseSocketUrl";
export default class DDBMuleSocket {
    socket = null;
    proxyUrl;
    socketUrl;
    socketPath;
    jobId = null;
    jobToken = null;
    lastSeq = 0;
    handlers = null;
    authenticated = false;
    constructor(proxyUrl) {
        this.proxyUrl = proxyUrl.replace(/\/$/, "");
        const { url, path } = parseSocketUrl(this.proxyUrl, "/mule");
        this.socketUrl = url;
        this.socketPath = path;
    }
    connect(handlers) {
        this.handlers = handlers;
        this.socket = io(this.socketUrl, {
            path: this.socketPath,
            transports: ["websocket"],
            reconnection: true,
            reconnectionAttempts: 10,
            reconnectionDelay: 1000,
            reconnectionDelayMax: 5000,
            timeout: 20000,
        });
        this.socket.on("connect", () => {
            logger.debug(`[DDBMuleSocket] connected ${this.socket?.id}`);
        });
        this.socket.on("connect_error", (err) => {
            logger.warn(`[DDBMuleSocket] connect_error: ${err.message}`);
            this.handlers?.onConnectError?.(err);
        });
        this.socket.on("event", (event) => {
            if (event.seq != null && event.seq > this.lastSeq)
                this.lastSeq = event.seq;
            if (event.kind === "error") {
                const payload = event.payload ?? {};
                this.handlers?.onError?.(payload.message ?? "Unknown error", !!payload.fatal);
            }
            else if (event.kind === "done") {
                this.handlers?.onDone?.(event.payload);
            }
            this.handlers?.onEvent(event);
        });
        this.socket.on("reconnect", async () => {
            logger.info(`[DDBMuleSocket] reconnected, resuming jobId=${this.jobId} lastSeq=${this.lastSeq}`);
            if (this.jobId && this.jobToken) {
                await this.resume();
            }
        });
    }
    ensureConnected() {
        if (!this.socket)
            throw new Error("DDBMuleSocket not connected, call connect() first");
        return this.socket;
    }
    auth(body) {
        const socket = this.ensureConnected();
        return new Promise((resolve) => {
            socket.emit("auth", body, (res) => {
                this.authenticated = !!res?.ok;
                resolve(res ?? { ok: false, message: "no ack" });
            });
        });
    }
    start(element, params) {
        const socket = this.ensureConnected();
        return new Promise((resolve) => {
            socket.emit("start", { element, params }, (res) => {
                if (res?.ok) {
                    this.jobId = res.jobId;
                    this.jobToken = res.jobToken;
                }
                resolve(res ?? { ok: false, message: "no ack" });
            });
        });
    }
    resume() {
        const socket = this.ensureConnected();
        if (!this.jobId || !this.jobToken) {
            return Promise.resolve({ ok: false, message: "no active job to resume" });
        }
        return new Promise((resolve) => {
            socket.emit("resume", {
                jobId: this.jobId,
                jobToken: this.jobToken,
                lastSeq: this.lastSeq,
            }, (res) => resolve(res ?? { ok: false, message: "no ack" }));
        });
    }
    cancel() {
        const socket = this.ensureConnected();
        if (!this.jobId || !this.jobToken) {
            return Promise.resolve({ ok: false, message: "no active job" });
        }
        return new Promise((resolve) => {
            socket.emit("cancel", { jobId: this.jobId, jobToken: this.jobToken }, (res) => {
                resolve(res ?? { ok: false, message: "no ack" });
            });
        });
    }
    close() {
        if (this.socket) {
            this.socket.disconnect();
            this.socket = null;
        }
        this.handlers = null;
        this.jobId = null;
        this.jobToken = null;
        this.lastSeq = 0;
        this.authenticated = false;
    }
}
