import ChangeHelper from "./ChangeHelper";
import AutoEffects from "./AutoEffects";
export default class EnchantmentEffects {
    static EnchantmentEffect(document, label, { transfer = false, disabled = false, origin = null, id = null, description = null, durationSeconds = null, durationRounds = null, durationTurns = null } = {}) {
        const effect = AutoEffects.BaseEffect(document, label, {
            transfer,
            disabled,
            description: description ?? undefined,
            durationSeconds: durationSeconds ?? undefined,
            durationRounds: durationRounds ?? undefined,
            durationTurns,
        });
        foundry.utils.setProperty(effect, "flags.dnd5e.type", "enchantment");
        effect._id = id ?? foundry.utils.randomID();
        effect.origin = origin ?? undefined;
        return effect;
    }
    static addMagicalBonus({ effect, nameAddition = null, bonus = null, bonusMode = "override", makeMagical = true }) {
        const name = nameAddition
            ? `, ${nameAddition}`
            : ` (${effect.name})`;
        const system = (effect.system ??= {});
        const changes = (system.changes ??= []);
        const change = ChangeHelper.overrideChange(`{}${name}`, 20, "name");
        changes.push(change);
        if (bonus !== null) {
            changes.push({
                key: "system.magicalBonus",
                type: bonusMode,
                value: `${bonus}`,
                priority: 20,
            });
        }
        if (makeMagical) {
            const magicalChange = ChangeHelper.addChange("mgc", 20, "system.properties");
            changes.push(magicalChange);
        }
        return effect;
    }
}
