    static convertToSingularDie(advancement) {
        if (!("configuration" in advancement) || !advancement.configuration)
            return advancement;
        const configuration = advancement.configuration;
        if (!("scale" in configuration) || !configuration.scale)
            return advancement;
        const scale = configuration.scale;
        advancement.title += ` (Die)`;
        for (const key of Object.keys(scale)) {
            scale[key].number = 1;
        }
        return advancement;
    }
