        const update = {
            title: name,
            hint,
            configuration: {
                allowDrops: true,
                pool: uuids.map((s) => {
                    return { uuid: s.uuid };
                }),
                choices: levelChoices,
                restriction: {
                    level: "0",
                    type: "spell",
                    list: spellListChoice ? [`class:${spellListChoice}`] : [],
                },
                type: "spell",
                spell: {
                    ability: abilities,
                    preparation: "",
                    uses: {
                        max: "",
                        per: "",
                        requireSlot: false,
                    },
                },
            },
        };
        advancement.updateSource(update);
        if (uuids.length > 0 || spellListChoice)
            return advancement;
        return undefined;
