    "turnStart",
    "turnEnd",
    "turnStartSource",
    "turnEndSource",
    "combatEnd",
    // Attack/Action triggers
    "1Action",
    "1Attack",
    "1Attack:mwak",
    "1Attack:rwak",
    "1Reaction",
    "1Save",
    "1Spell",
    // Condition triggers
    "isAttacked",
    "isDamaged",
    "DamageDealt",
    "isSave",
    "isInitiative",
    "Initiative",
    // Skill check triggers
    "isSkill.acr",
    "isSkill.ath",
    "isSkill.his",
    "isSkill.ins",
    "isSkill.inv",
    "isSkill.itm",
    "isSkill.per",
    "isSkill.prf",
    "isSkill.ste",
    // attacked
    "1Hit",
    "1Hit:mwak",
    "1Hit:rwak",
